from __future__ import annotations

import re
from dataclasses import dataclass


# Keep numbers as normalized decimal strings, avoiding Python's limits on
# decimal-string-to-int conversion for arbitrarily large version components.
_Core = tuple[str, str, str]

_NUMBER = r"(?:0|[1-9][0-9]*)"
_IDENTIFIER = r"[0-9A-Za-z-]+"
_NUMBER_RE = re.compile(_NUMBER)
_VERSION_RE = re.compile(
    rf"({_NUMBER})\.({_NUMBER})\.({_NUMBER})"
    rf"(?:-({_IDENTIFIER}(?:\.{_IDENTIFIER})*))?"
    rf"(?:\+{_IDENTIFIER}(?:\.{_IDENTIFIER})*)?"
)


def _is_digits(s: str) -> bool:
    return bool(s) and all("0" <= c <= "9" for c in s)


def _increment(s: str) -> str:
    digits = list(s)
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] != "9":
            digits[i] = chr(ord(digits[i]) + 1)
            return "".join(digits)
        digits[i] = "0"
    return "1" + "".join(digits)


def _bump(core: _Core, index: int) -> _Core:
    parts = list(core)
    parts[index] = _increment(parts[index])
    for i in range(index + 1, 3):
        parts[i] = "0"
    return parts[0], parts[1], parts[2]


@dataclass(frozen=True)
class _Version:
    core: _Core
    prerelease: tuple[str, ...] | None = None

    def key(self) -> tuple:
        core_key = tuple((len(n), n) for n in self.core)
        if self.prerelease is None:
            prerelease_key = (1,)
        else:
            identifiers = tuple(
                (0, len(identifier), identifier)
                if _is_digits(identifier)
                else (1, identifier)
                for identifier in self.prerelease
            )
            prerelease_key = (0, identifiers)
        return core_key, prerelease_key


def _parse_version(text: str) -> _Version | None:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        return None

    major, minor, patch, prerelease_text = match.groups()
    prerelease = (
        None if prerelease_text is None else tuple(prerelease_text.split("."))
    )
    if prerelease is not None:
        for identifier in prerelease:
            if (
                _is_digits(identifier)
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                return None

    return _Version((major, minor, patch), prerelease)


def _parse_pattern(pattern: str) -> tuple[_Version, int]:
    """Return the lower version and the number of explicitly written numbers."""
    if "+" in pattern:
        raise ValueError(f"Build metadata is not allowed in ranges: {pattern!r}")

    full = _parse_version(pattern)
    if full is not None:
        return full, 3

    parts = pattern.split(".")
    if not 1 <= len(parts) <= 3:
        raise ValueError(f"Invalid range pattern: {pattern!r}")

    numbers: list[str] = []
    wildcard_seen = False
    for part in parts:
        if part in ("x", "X", "*"):
            wildcard_seen = True
        elif not wildcard_seen and _NUMBER_RE.fullmatch(part) is not None:
            numbers.append(part)
        else:
            raise ValueError(f"Invalid range pattern: {pattern!r}")

    count = len(numbers)
    numbers.extend(["0"] * (3 - count))
    return _Version((numbers[0], numbers[1], numbers[2])), count


def _expand(
    operator: str, version: _Version, count: int
) -> list[tuple[str, _Version]]:
    """Expand one comparator into primitive precedence comparisons."""
    if count == 0:
        if operator:
            raise ValueError("A numberless pattern must not have an operator")
        return []

    if operator == "^":
        index = next(
            (i for i in range(count) if version.core[i] != "0"),
            count - 1,
        )
        upper = _Version(_bump(version.core, index), ("0",))
        return [(">=", version), ("<", upper)]

    if operator == "~":
        index = 0 if count == 1 else 1
        upper = _Version(_bump(version.core, index), ("0",))
        return [(">=", version), ("<", upper)]

    if count == 3:
        return [(operator or "=", version)]

    next_core = _bump(version.core, count - 1)
    upper = _Version(next_core, ("0",))

    if operator in ("", "="):
        return [(">=", version), ("<", upper)]
    if operator == ">":
        return [(">=", _Version(next_core))]
    if operator == ">=":
        return [(">=", version)]
    if operator == "<":
        return [("<", _Version(version.core, ("0",)))]
    if operator == "<=":
        return [("<", upper)]

    raise ValueError(f"Invalid operator: {operator!r}")


@dataclass
class _Alternative:
    bounds: list[tuple[str, tuple]]
    prerelease_cores: set[_Core]


def _parse_range(range_expr: str) -> list[_Alternative]:
    alternatives: list[_Alternative] = []

    # Only literal spaces separate comparators, as specified.
    for text in range_expr.strip(" ").split("||"):
        text = text.strip(" ")
        if not text:
            raise ValueError("Empty range or range alternative")

        bounds: list[tuple[str, tuple]] = []
        prerelease_cores: set[_Core] = set()

        for token in text.split(" "):
            if not token:
                continue

            operator = ""
            pattern = token
            for candidate in ("<=", ">=", "=", "<", ">", "^", "~"):
                if token.startswith(candidate):
                    operator = candidate
                    pattern = token[len(candidate):]
                    break

            version, count = _parse_pattern(pattern)

            # Record only pre-releases explicitly written in the range,
            # never the synthetic "-0" upper bounds.
            if count == 3 and version.prerelease is not None:
                prerelease_cores.add(version.core)

            bounds.extend(
                (op, bound.key())
                for op, bound in _expand(operator, version, count)
            )

        alternatives.append(_Alternative(bounds, prerelease_cores))

    return alternatives


def _holds(actual: tuple, operator: str, bound: tuple) -> bool:
    if operator == "=":
        return actual == bound
    if operator == "<":
        return actual < bound
    if operator == "<=":
        return actual <= bound
    if operator == ">":
        return actual > bound
    if operator == ">=":
        return actual >= bound
    raise AssertionError(f"Unexpected internal operator: {operator!r}")


def best_match(versions: list[str], range_expr: str) -> str | None:
    """Return the first highest-precedence version satisfying range_expr."""
    # Validate before examining versions, including when versions is empty.
    alternatives = _parse_range(range_expr)

    best: str | None = None
    best_key: tuple | None = None

    for original in versions:
        version = _parse_version(original)
        if version is None:
            continue

        key = version.key()
        for alternative in alternatives:
            if (
                version.prerelease is not None
                and version.core not in alternative.prerelease_cores
            ):
                continue

            if all(
                _holds(key, operator, bound)
                for operator, bound in alternative.bounds
            ):
                # Strict comparison preserves the first occurrence on ties.
                if best_key is None or key > best_key:
                    best = original
                    best_key = key
                break

    return best
